const today = new Date().toISOString().slice(0, 10);

const callLog = $('Read Call Log').all().map(i => i.json);
const qualified = $('Read Qualified Leads').all().map(i => i.json);

const todayCalls = callLog.filter(r => (r['Started At'] || '').startsWith(today));
const totalCalled = todayCalls.length;
const connected = todayCalls.filter(r => r['Call Status'] === 'ended' || r['Call Status'] === 'completed').length;
const noAnswer = todayCalls.filter(r => (r['Disconnection Reason'] || '').includes('no_answer') || (r['Disconnection Reason'] || '').includes('voicemail')).length;

const todayLeads = qualified.filter(r => (r['Processed At'] || '').startsWith(today));
const hot = todayLeads.filter(r => (r['Lead Score'] || '').includes('HOT')).length;
const warm = todayLeads.filter(r => (r['Lead Score'] || '').includes('WARM')).length;
const cold = todayLeads.filter(r => (r['Lead Score'] || '').includes('COLD')).length;

const connectRate = totalCalled > 0 ? Math.round((connected / totalCalled) * 100) : 0;
const conversionRate = connected > 0 ? Math.round((hot / connected) * 100) : 0;

return [{
  json: { date: today, totalCalled, connected, noAnswer, hot, warm, cold, connectRate, conversionRate }
}];

